-- Fiche Les nombres (CP) - anglais, notion 'en_nombres'. Relancer ce script remplace le contenu de la fiche.
insert into contenu_cours (classe, matiere, titre, contenu, statut, notion_id)
select 'cp', 'english', 'Les nombres', $fiche$
